<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { Clapperboard, Gem, Radar, Zap, ArrowUpRight, Check, Copy, Wallet, ShieldCheck, X, Star, QrCode, RefreshCw, ChevronRight, Ticket, Send, LockKeyhole, Film } from 'lucide-vue-next'
import BillingPaymentIcon from './BillingPaymentIcon.vue'
import { accountApi as api } from '@/accountApi'
import { tr, language } from '@/i18n'
import { friendlyTonAddress, compactTonAddress, validatedTransaction } from '@/tonPayments'
import type { TonConnectUI } from '@tonconnect/ui'
const pricing = ref<HTMLElement>()
function showPlans(){pricing.value?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}
const props = defineProps<{ account: any }>()
const emit = defineEmits(['changed'])
const plans = ref<any[]>([]), selected = ref(''), method = ref('usdt_ton'), orders = ref<any[]>([]), activations = ref<any[]>([]), total = ref(0), offset = ref(0)
const busy = ref(false), loading = ref(true), error = ref(''), note = ref(''), promo = ref(''), latest = ref<any>(null)
const modal = ref<'invoice'|'unavailable'|null>(null), dialog = ref<HTMLDialogElement>(), otp = ref('')
let disposed = false, polling = false, timer: ReturnType<typeof setInterval>|undefined, ton: TonConnectUI|undefined, unsubscribe: (()=>void)|undefined
const chosen = computed(()=>plans.value.find(p=>p.id===selected.value))
const methods = computed(()=>chosen.value?.methods?.filter((m:any)=>m.id!=='stars') || [])
const selectedMethod = computed(()=>methods.value.find((m:any)=>m.id===method.value))
const walletLabel = computed(()=>{ try{return props.account.ton_address ? compactTonAddress(props.account.ton_address) : ''} catch{return ''} })
const pro = computed(()=>['active_paid','trial'].includes(props.account.subscription_status))
const features = computed(()=>[
 {icon:Clapperboard,tone:'violet',title:tr('Горячие новинки и эксклюзивы','New releases & exclusives'),text:tr('Мгновенный доступ к премьерам, закрытым подборкам и фильмам до цифрового релиза.','Instant access to premieres, curated collections and films before digital release.')},
 {icon:Gem,tone:'blue',title:tr('Честный 4K Ultra HD','True 4K Ultra HD'),text:tr('Максимальный битрейт, кристальная картинка и оригинальные аудиодорожки.','Maximum bitrate, crystal-clear picture and original audio tracks.')},
 {icon:Radar,tone:'mint',title:tr('Movie Radar · Умный радар трендов','Movie Radar · Discover what’s next'),text:tr('Самые обсуждаемые фильмы в реальном времени и персональные рекомендации.','Real-time film trends and personal recommendations.')},
 {icon:Zap,tone:'amber',title:tr('Просмотр без ограничений','Uninterrupted movie nights'),text:tr('Без рекламы. Приоритетный доступ к скоростным медиа-нодам и загрузка.','No ads. Priority access to high-speed media nodes and downloads.')}
])
function discount(p:any){const base=Number(plans.value.find(x=>x.days===30)?.usd||0)*(p.days===180?6:12);return base>0?Math.max(0,Math.floor((1-Number(p.usd)/base)*100)):0}
function planName(p:any){return p.days===30?tr('1 месяц','1 month'):p.days===180?tr('6 месяцев','6 months'):p.days===365?tr('12 месяцев','12 months'):p.title}
function usd(v:any){return Number(v||0).toLocaleString(language.value==='ru'?'ru-RU':'en-US',{style:'currency',currency:'USD',minimumFractionDigits:2})}
function money(value:any,decimals=9){return Number(value).toLocaleString(language.value==='ru'?'ru-RU':'en-US',{maximumFractionDigits:decimals})}
function priceFor(p:any){const m=p.methods?.find((m:any)=>m.id===method.value);return m?.price?money(m.price,m.decimals??9):null}
function date(s?:string){return s?new Date(s).toLocaleDateString(language.value==='ru'?'ru-RU':'en-US',{day:'numeric',month:'short',year:'numeric'}):'—'}
function status(s:string){return ({pending:tr('Ожидает оплаты','Awaiting payment'),paid:tr('Оплачено','Paid'),expired:tr('Истёк','Expired'),refunded:tr('Возврат','Refunded'),active:tr('Активна','Active'),trial:tr('Пробная','Trial'),canceled:tr('Отменена','Canceled')})[s]||s}
function effectiveStatus(o:any){return o.status==='pending'&&new Date(o.expires_at).getTime()<Date.now()?'expired':o.status}
function short(value:string){return value.length>24?value.slice(0,10)+'…'+value.slice(-8):value}
function qr(svg:string){return 'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(svg)))}
function close(){modal.value=null;otp.value=''}
watch(modal,async value=>{await nextTick();if(disposed)return;if(value&&!dialog.value?.open)dialog.value?.showModal();else if(!value&&dialog.value?.open)dialog.value.close()})
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';note.value='';try{await fn()}catch(e:any){if(e.code==='PAYMENT_METHOD_UNAVAILABLE'||e.code==='STARS_UNAVAILABLE'){modal.value='unavailable'}else error.value=({TON_WALLET_MISMATCH:tr('Подключён другой кошелёк. Выберите кошелёк, указанный в счёте.','A different wallet is connected. Select the wallet shown in this invoice.'),PAYMENT_ORDER_EXPIRED:tr('Срок счёта истёк. Создайте новый счёт.','This invoice has expired. Create a new one.'),TON_ADDRESS_INVALID:tr('Не удалось проверить адрес TON. Повторно подключите кошелёк.','Unable to validate the TON address. Reconnect your wallet.'),PAYMENT_REQUEST_INVALID:tr('Не удалось проверить платёжный запрос. Создайте новый счёт.','Unable to validate this payment request. Create a new invoice.')} as Record<string,string>)[e.code||e.message]||e.message||tr('Не удалось выполнить действие. Попробуйте ещё раз.','Unable to complete this action. Please try again.')}finally{busy.value=false}}
async function history(){const [o,a]=await Promise.all([api('/billing/orders?offset='+offset.value),api('/billing/activations')]);if(disposed)return;orders.value=o.items;total.value=o.total;activations.value=a}
async function refresh(){if(polling||disposed)return;polling=true;try{const pending=new Set(orders.value.filter(o=>o.status==='pending').map(o=>o.id));await history();if(orders.value.some(o=>pending.has(o.id)&&o.status==='paid'))emit('changed');if(latest.value){const order=orders.value.find(o=>o.id===latest.value.id);if(order){latest.value={...latest.value,...order};if(order.status==='paid'){note.value=tr('Оплата подтверждена. Добро пожаловать в PRO!','Payment confirmed. Welcome to PRO!');modal.value=null;emit('changed')}}}}catch(e:any){error.value=e.message}finally{polling=false}}
function choose(p:any){selected.value=p.id;note.value='';error.value=''}
async function copy(value:string){try{await navigator.clipboard.writeText(value);note.value=tr('Скопировано.','Copied.')}catch{error.value=tr('Выделите и скопируйте значение вручную.','Select and copy the value manually.')}}
async function redeem(){await action(async()=>{await api('/me/promo','POST',{code:promo.value});promo.value='';await history();emit('changed');note.value=tr('Промокод активирован. Приятного просмотра!','Promo code activated. Enjoy the show!')})}
async function ensureTon(){if(ton)return ton;const {TonConnectUI}=await import('@tonconnect/ui');ton=new TonConnectUI({manifestUrl:window.location.origin+'/tonconnect-manifest.json'});unsubscribe=ton.onStatusChange(async wallet=>{if(!wallet||disposed)return;const proof=wallet.connectItems?.tonProof;if(proof&&'proof' in proof){try{await api('/billing/wallet','POST',{address:wallet.account.address,network:wallet.account.chain,proof:proof.proof});note.value=tr('Проверяем кошелёк в сети…','Verifying wallet on chain…');for(let n=0;n<40;n++){await new Promise(r=>setTimeout(r,750));if(disposed)return;const a=await api('/account');emit('changed');if(a.ton_verification_status==='failed')throw new Error(tr('Не удалось подтвердить кошелёк. Подключите его повторно.','Wallet verification failed. Reconnect your wallet.'));if(!a.ton_verification_status&&a.ton_address){note.value=tr('Кошелёк подтверждён. Теперь можно оплатить выбранный тариф.','Wallet verified. You can now pay for your selected plan.');break}}}catch(e:any){error.value=e.message}}});await ton.connectionRestored;return ton}
async function connect(){await action(async()=>{const client=await ensureTon();const challenge=await api('/billing/wallet/challenge','POST',{});client.setConnectRequestParameters({state:'ready',value:{tonProof:challenge.payload}});if(client.connected)await client.disconnect();await client.openModal()})}
async function disconnect(){await action(async()=>{await api('/billing/wallet','DELETE',undefined,otp.value);if(ton?.connected)await ton.disconnect();emit('changed')})}
async function openCrypto(){if(!chosen.value)return;if(!selectedMethod.value?.available){modal.value='unavailable';return}await action(async()=>{const isTon=['ton','usdt_ton','gram'].includes(method.value);if(isTon&&!props.account.ton_address){note.value=tr('Сначала подключите и подтвердите TON-кошелёк.','Connect and verify your TON wallet first.');await ensureTon();const challenge=await api('/billing/wallet/challenge','POST',{});ton!.setConnectRequestParameters({state:'ready',value:{tonProof:challenge.payload}});if(ton!.connected)await ton!.disconnect();await ton!.openModal();return}offset.value=0;latest.value=await api('/billing/orders','POST',{plan_id:selected.value,provider:method.value,request_key:crypto.randomUUID()});modal.value='invoice';await history();for(let n=0;n<40&&latest.value?.payment?.preparation!=='ready';n++){await new Promise(r=>setTimeout(r,750));if(disposed)return;await refresh()}})}
async function sendTon(){await action(async()=>{const client=await ensureTon();if(!client.connected||!client.wallet){error.value=tr('Подключите тот же TON-кошелёк в этом браузере. QR-код также доступен ниже.','Connect the same TON wallet in this browser, or use the QR code below.');return}const tx=validatedTransaction(latest.value.payment.transaction,client.wallet.account.address);await client.sendTransaction(tx);note.value=tr('Транзакция отправлена. Ждём подтверждения сети — страницу можно не закрывать.','Transaction sent. Waiting for network confirmation.');await refresh()})}
function openInvoice(order:any){const webApp=(window as any).Telegram?.WebApp;if(webApp?.openInvoice){webApp.openInvoice(order.invoice_url,()=>refresh());return}const w=window.open(order.invoice_url,'_blank','noopener,noreferrer');if(!w)note.value=tr('Счёт готов. Нажмите «Открыть счёт в Telegram» ниже.','Your invoice is ready. Select “Open invoice in Telegram” below.')}
async function createStars(planId:string){offset.value=0;const target=window.open('about:blank','_blank');try{const order=await api('/billing/orders','POST',{plan_id:planId,provider:'stars',request_key:crypto.randomUUID()});if(disposed){target?.close();return}latest.value=order;note.value=tr('Подготовка счёта…','Preparing invoice…');for(let n=0;n<40;n++){await new Promise(r=>setTimeout(r,750));if(disposed){target?.close();return}await history();const ready=orders.value.find(o=>o.id===order.id)||(order.invoice_url?order:null);if(ready?.invoice_url){latest.value=ready;const webApp=(window as any).Telegram?.WebApp;if(webApp?.openInvoice){target?.close();openInvoice(ready)}else if(target){target.opener=null;target.location.replace(ready.invoice_url)}else openInvoice(ready);note.value='';return}}target?.close();throw new Error(tr('Счёт ещё готовится. Повторите открытие из истории.','Invoice is still preparing. Open it from history shortly.'))}catch(e){target?.close();throw e}}
async function stars(){if(busy.value)return;error.value='';note.value='';if(!chosen.value)return;await action(()=>createStars(selected.value))}
onMounted(async()=>{await action(async()=>{plans.value=await api('/billing/plans');if(disposed)return;selected.value=(plans.value.find(p=>p.days===180)||plans.value[0])?.id||'';await history()});loading.value=false;timer=setInterval(()=>{if(latest.value?.status==='pending'||orders.value.some(o=>o.status==='pending'))refresh()},2000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(timer);unsubscribe?.();if(dialog.value?.open)dialog.value.close();otp.value=''})
</script>

<template>
<section class="cinema-billing">
  <header class="billing-intro"><div><p class="eyebrow">KINOSOTA PRO</p><h2>{{tr('Больше, чем просто кино.','Your next great movie night.')}}</h2><p class="muted">{{tr('Выберите свой ритм. Всё остальное — уже включено.','Choose your rhythm. Everything else is included.')}}</p></div><span class="secure-tag"><ShieldCheck :size="16"/>{{tr('Безопасная оплата','Secure checkout')}}</span></header>
  <p v-if="error&&!modal" role="alert" class="notice error">{{error}}</p><p v-if="note&&!modal" role="status" class="notice">{{note}}</p>
  <div class="membership-strip"><Film class="membership-decoration" :size="180" aria-hidden="true"/><div class="membership-icon"><Gem :size="27"/></div><div><span class="eyebrow">{{tr('ВАШ ТАРИФ','YOUR MEMBERSHIP')}}</span><strong>{{pro?'PRO':tr('Базовый · FREE','Basic · FREE')}}</strong></div><div class="membership-expiry"><span>{{pro?tr('Действует до','Active until'):tr('Следующий уровень впечатлений','Your next level of cinema')}}</span><b><template v-if="pro">{{account.subscription_lifetime?tr('Бессрочно','Lifetime'):date(account.subscription_expires_at)}}</template><button v-else class="upgrade-button" @click="showPlans" data-testid="show-pro-plans">{{tr('Откройте PRO','Unlock PRO')}}<ArrowUpRight :size="17"/></button></b></div></div>
  <div class="benefit-grid" data-testid="pro-bento"><article v-for="f in features" :key="f.title" :class="['benefit',f.tone]"><span class="benefit-icon"><component :is="f.icon" :size="23"/></span><div><h3>{{f.title}}</h3><p>{{f.text}}</p></div></article></div>
  <section ref="pricing" class="pricing-section" data-testid="pro-plans"><div class="section-label"><div><p class="eyebrow">{{tr('ВАШ БИЛЕТ В PRO','YOUR PASS TO PRO')}}</p><h3>{{tr('Один доступ. Больше возможностей.','One membership. More possibilities.')}}</h3></div><span class="muted">{{tr('Без автопродления','No auto-renewal')}}</span></div>
  <p v-if="loading" class="muted" role="status">{{tr('Загружаем тарифы…','Loading plans…')}}</p><p v-else-if="!plans.length" class="notice">{{tr('Тарифы скоро появятся. Обновите страницу позже.','Plans will be available soon. Please check back later.')}}</p>
  <div class="plan-grid" role="group" :aria-label="tr('Выбор тарифа','Choose your plan')"><button v-for="p in plans" :key="p.id" :class="['plan-card',{chosen:selected===p.id,popular:p.days===180}]" :aria-pressed="selected===p.id" @click="choose(p)" :data-days="p.days"><span class="plan-badge" :class="{year:p.days===365}">{{p.days===180?tr('ПОПУЛЯРНЫЙ','POPULAR')+(discount(p)>0?' · −'+discount(p)+'%':''):p.days===365?tr('МАКСИМУМ ВЫГОДЫ','BEST VALUE')+(discount(p)>0?' · −'+discount(p)+'%':''):tr('ЗНАКОМСТВО С PRO','START WITH PRO')}}</span><span class="plan-top"><strong>{{planName(p)}}</strong><span class="radio-check"><Check v-if="selected===p.id" :size="14"/></span></span><span class="plan-caption">{{p.days===30?tr('Базовый старт','A perfect start'):p.days===180?tr('Для тех, кто любит кино','For the love of cinema'):tr('Год больших историй','A year of great stories')}}</span><span class="price-line"><span class="plan-price">{{usd(p.usd)}}</span><s v-if="p.days>30&&plans[0]?.usd">{{usd(Number(plans.find(x=>x.days===30)?.usd||0)*(p.days===180?6:12))}}</s></span><span class="plan-period">{{tr('за весь период · ','for the full period · ')}}{{p.days}} {{tr('дней','days')}}</span><span class="plan-equivalent">{{priceFor(p)?priceFor(p)+' '+(selectedMethod?.symbol||''):tr('Цена валюты настраивается','Currency pricing pending')}}<span v-if="p.stars"> · ★ {{p.stars}}</span></span></button></div>
  </section>
  <section class="checkout-surface"><div class="payment-methods-block"><div class="section-label"><div><p class="eyebrow">{{tr('КАК ВАМ УДОБНЕЕ','YOUR WAY TO PAY')}}</p><h3>{{tr('Криптовалюта или Telegram Stars','Crypto or Telegram Stars')}}</h3></div><span class="checkout-safe"><LockKeyhole :size="18"/>{{tr('Безопасная оплата','Secure checkout')}}</span></div>
    <div class="method-grid" role="group" :aria-label="tr('Валюта и сеть','Currency and network')"><button v-for="m in methods" :key="m.id" :aria-pressed="method===m.id" :class="['method',{selected:method===m.id}]" @click="method=m.id"><span :class="['coin','coin-'+m.id]"><BillingPaymentIcon :method="m.id" :symbol="m.symbol"/></span><span><strong>{{m.symbol}}</strong><small>{{m.network}}</small></span><Check v-if="method===m.id" :size="15"/></button></div></div>
    <div class="wallet-row"><Wallet :size="20"/><div><strong>{{tr('TON-кошелёк','TON wallet')}}</strong><small>{{walletLabel||tr('Tonkeeper · Wallet · MyTonWallet','Tonkeeper · Wallet · MyTonWallet')}}</small></div><button v-if="walletLabel" class="icon-button" @click="copy(friendlyTonAddress(account.ton_address))" :aria-label="tr('Скопировать адрес TON','Copy TON address')"><Copy :size="17"/></button><button class="text-button" @click="connect">{{walletLabel?tr('Другой кошелёк','Switch wallet'):tr('Подключить','Connect')}}<ArrowUpRight :size="15"/></button></div>
    <div v-if="walletLabel&&account.two_factor_enabled" class="factor-row"><label>{{tr('Код 2FA для отвязки кошелька','2FA code to unlink wallet')}}<input v-model="otp" autocomplete="one-time-code" maxlength="64"/></label><button class="text-button" @click="disconnect">{{tr('Отвязать','Unlink')}}</button></div>
    <div class="checkout-total"><div><small>{{tr('К оплате · ','Total · ')}}{{chosen?planName(chosen):'—'}}</small><strong>{{selectedMethod?.price?money(selectedMethod.price,selectedMethod.decimals??9)+' '+selectedMethod.symbol:tr('Цена настраивается','Pricing pending')}}</strong><span v-if="selectedMethod?.id==='bep20'" class="muted">Binance-Peg USDT · BNB Smart Chain</span></div><button class="crypto-button" @click="openCrypto"><QrCode :size="19"/>{{tr('Перейти к оплате','Continue to payment')}}<ChevronRight :size="18"/></button></div>
    <div class="stars-checkout"><span class="stars-orbit"><Star :size="25" fill="currentColor"/></span><div><h4>Telegram Stars</h4><p>{{tr('Оплата внутри Telegram. Быстро и привычно.','Pay inside Telegram. Simple and familiar.')}}</p></div><button class="stars-button" @click="stars" data-testid="pay-stars">{{tr('Оплатить ★ Telegram Stars','Pay ★ Telegram Stars')}}<span v-if="chosen?.stars"> · {{chosen.stars}}</span></button></div>
    <p class="checkout-footnote"><ShieldCheck :size="15"/>{{tr('Доступ включится после подтверждения сети или Telegram. Мы не храним ключи от ваших кошельков.','Access activates after confirmation by the network or Telegram. Your wallet keys stay yours.')}}</p>
  </section>
  <form class="promo-surface" @submit.prevent="redeem"><span class="promo-icon"><Ticket :size="25"/></span><div><h3>{{tr('Есть промокод?','Have a promo code?')}}</h3><p>{{tr('Ваш следующий сеанс — с бонусом.','A little extra for your next movie night.')}}</p></div><label class="sr-only" for="cinema-promo">{{tr('Промокод','Promo code')}}</label><input id="cinema-promo" v-model="promo" required maxlength="128" :placeholder="tr('Введите промокод','Enter promo code')"/><button class="secondary" :disabled="busy">{{tr('Активировать','Redeem')}}</button></form>
  <section class="history-surface"><div class="section-label"><h3>{{tr('Покупки и активации','Purchases & activations')}}</h3><span class="muted">{{total}}</span></div><div v-if="!orders.length&&!activations.length" class="empty-history"><span class="history-illustration" aria-hidden="true"><img src="/account/pro-history-cinema.webp" alt="" width="194" height="122"/></span><div><strong>{{tr('Здесь начнётся ваша PRO-история','Your PRO story starts here')}}</strong><p>{{tr('После первой покупки здесь появятся её статус и детали.','Your first purchase and its status will appear here.')}}</p></div></div><div v-else class="table-scroll"><table><thead><tr><th>{{tr('Дата и тариф','Date & plan')}}</th><th>{{tr('Способ и сумма','Method & amount')}}</th><th>{{tr('Статус','Status')}}</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{date(o.created_at)}}<small>PRO · {{o.duration_days}} {{tr('дней','days')}}</small></td><td>{{o.amount_display||o.amount}} {{o.payment?.symbol||o.provider}}<small>{{o.payment?.network}}</small></td><td><span :class="['order-status',effectiveStatus(o)]">{{status(effectiveStatus(o))}}</span><button v-if="effectiveStatus(o)==='pending'" class="text-button" @click="latest=o;modal='invoice'">{{tr('Открыть','Open')}}</button></td></tr><tr v-for="(a,i) in activations" :key="'a'+i"><td>{{date(a.created_at)}}<small>{{a.title}}</small></td><td>{{tr('Активация','Activation')}}<small>{{tr('До ','Until ')}}{{date(a.expires_at)}}</small></td><td>{{status(a.status)}}</td></tr></tbody></table></div><div v-if="total>50" class="pager"><button class="secondary" :disabled="offset===0" @click="offset-=50;history()">{{tr('Назад','Previous')}}</button><button class="secondary" :disabled="offset+50>=total" @click="offset+=50;history()">{{tr('Далее','Next')}}</button></div></section>
  <dialog ref="dialog" class="payment-dialog" @cancel.prevent="close" @close="close" @click="($event.target===dialog)&&close()"><div class="dialog-body" v-if="modal"><button class="close-dialog" @click="close" :aria-label="tr('Закрыть','Close')"><X :size="22"/></button>
    <template v-if="modal==='unavailable'"><span class="dialog-emblem violet"><Wallet :size="28"/></span><p class="eyebrow">{{tr('СКОРО БУДЕТ ДОСТУПНО','COMING SOON')}}</p><h2>{{tr('Этот способ оплаты настраивается','This payment method is being set up')}}</h2><p class="muted">{{tr('Приём платежей в этой валюте временно настраивается администратором, выберите другой способ.','The administrator is setting up payments in this currency. Please choose another method.')}}</p><button class="crypto-button full" @click="close">{{tr('Выбрать другой способ','Choose another method')}}</button></template>
    <template v-if="modal==='invoice'&&latest"><span class="dialog-emblem" :class="latest.provider==='stars'?'amber':'violet'"><component :is="latest.provider==='stars'?Star:QrCode" :size="28"/></span><p class="eyebrow">{{tr('ВАШ СЧЁТ','YOUR INVOICE')}}</p><h2>PRO · {{latest.duration_days}} {{tr('дней','days')}}</h2><div class="invoice-amount">{{latest.amount_display}} <span>{{latest.provider==='stars'?'★':latest.payment?.symbol}}</span></div><p class="network-label">{{latest.payment?.network||'Telegram Stars'}}</p>
    <template v-if="latest.provider==='stars'"><a class="stars-button full" :href="latest.invoice_url" target="_blank" rel="noopener noreferrer">{{tr('Открыть счёт в Telegram','Open invoice in Telegram')}}<ArrowUpRight :size="18"/></a><p class="muted">{{tr('Подписка активируется после подтверждения Telegram. Возвращайтесь сюда — статус обновится автоматически.','Your membership activates after Telegram confirms payment. Return here to see the updated status.')}}</p></template>
